# Expected values are SymPy's outputs for the same calls (meijerint_indefinite, meijerint_definite and meijerint_inversion).

skip_unless_full_tests()

skip_on_cran()

x <- Symbol("x"); y <- Symbol("y"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); s <- Symbol("s"); t <- Symbol("t"); z <- Symbol("z")
ap <- Symbol("ap", positive = TRUE); bp <- Symbol("bp", positive = TRUE); sp <- Symbol("sp", positive = TRUE)
mu <- Symbol("mu", positive = TRUE); sigma <- Symbol("sigma", positive = TRUE); alpha <- Symbol("alpha", positive = TRUE)
n <- Symbol("n", integer = TRUE); r <- Symbol("r", real = TRUE)
mi_fmt <- function(v) {
  if (is.null(v)) return("None")
  if (is.list(v) && !is_sym(v)) return(paste0("(", paste(vapply(v, mi_fmt, ""), collapse = ", "), ")"))
  gsub("\n", " ", sstr(v))
}

test_that("meijerint_indefinite, meijerint_definite and meijerint_inversion match SymPy", {
  expect_equal(mi_fmt(meijerint_indefinite(exp(x), x)), "exp(x)")
  expect_equal(mi_fmt(meijerint_indefinite(sin(x), x)), "-cos(x)")
  expect_equal(mi_fmt(meijerint_indefinite(cos(x), x)), "sin(x)")
  expect_equal(mi_fmt(meijerint_indefinite(x*exp(-x), x)), "-x*exp(-x) - exp(-x)")
  expect_equal(mi_fmt(meijerint_indefinite(x^2*exp(-x), x)), "-x^2*exp(-x) - 2*x*exp(-x) - 2*exp(-x)")
  expect_equal(mi_fmt(meijerint_indefinite(exp(-x^2), x)), "sqrt(pi)*erf(x)/2")
  expect_equal(mi_fmt(meijerint_indefinite(sinh(x), x)), "cosh(x)")
  expect_equal(mi_fmt(meijerint_indefinite(cosh(x), x)), "sinh(x)")
  expect_equal(mi_fmt(meijerint_indefinite(log(x), x)), "Piecewise((0, (Abs(x) < 1) & (1/Abs(x) < 1)), (x*log(x) - x, Abs(x) < 1), (-x*log(1/x) - x, 1/Abs(x) < 1), (-x*meijerg(((0,), (1, 1)), ((0, 0), (-1,)), x) + x*meijerg(((0, 1, 1), ()), ((), (-1, 0, 0)), x), True))")
  expect_equal(mi_fmt(meijerint_indefinite(x*sin(x), x)), "-x*cos(x) + sin(x)")
  expect_equal(mi_fmt(meijerint_indefinite(x*cos(x), x)), "x*sin(x) + cos(x)")
  expect_equal(mi_fmt(meijerint_indefinite(besselj(0, x), x)), "x*hyper((1/2,), (1, 3/2), -x^2/4)")
  expect_equal(mi_fmt(meijerint_indefinite(x*besselj(0, x), x)), "x*besselj(1, x)")
  expect_equal(mi_fmt(meijerint_indefinite(x*besseli(0, x), x)), "x*besseli(1, x)")
  expect_equal(mi_fmt(meijerint_indefinite(besselj(1, x), x)), "-besselj(0, x)")
  expect_equal(mi_fmt(meijerint_indefinite(besselj(1, x)^2/x, x)), "-besselj(0, x)^2/2 - besselj(1, x)^2/2")
  expect_equal(mi_fmt(meijerint_indefinite(besselj(0, x)*besselj(1, x), x)), "-besselj(0, x)^2/2")
  expect_equal(mi_fmt(meijerint_indefinite(x^2*besselj(0, x)*besselj(1, x), x)), "x^2*besselj(1, x)^2/2")
  expect_equal(mi_fmt(meijerint_indefinite(besselj(1, x^2)*x, x)), "-besselj(0, x^2)/2")
  expect_equal(mi_fmt(meijerint_indefinite(1/(1 + x), x)), "Piecewise((-log(1/(x + 1)) + log(x + 1), (Abs(x + 1) < 1) & (1/Abs(x + 1) < 1)), (log(x + 1), Abs(x + 1) < 1), (-log(1/(x + 1)), 1/Abs(x + 1) < 1), (-meijerg(((), (1, 1)), ((0, 0), ()), x + 1) + meijerg(((1, 1), ()), ((), (0, 0)), x + 1), True))")
  expect_equal(mi_fmt(meijerint_indefinite(x*sqrt(2*x + 3), x)), "2*x^2*sqrt(2*x + 3)/5 + x*sqrt(2*x + 3)/5 - 3*sqrt(2*x + 3)/5")
  expect_equal(mi_fmt(meijerint_indefinite(erf(x), x)), "x*erf(x) + exp(-x^2)/sqrt(pi)")
  expect_equal(mi_fmt(meijerint_indefinite(x^x^x, x)), "None")
  expect_equal(mi_fmt(meijerint_indefinite(sin(x)/x, x)), "Si(x)")
  expect_equal(mi_fmt(meijerint_indefinite(exp(-x)*x^n, x)), "n*gamma(n + 1)*lowergamma(n + 1, x)/gamma(n + 2) + gamma(n + 1)*lowergamma(n + 1, x)/gamma(n + 2)")
  expect_equal(mi_fmt(meijerint_indefinite(sqrt(x), x)), "Piecewise((2*x^(3/2)/3, Abs(x) < 1), (x^(3/2)*meijerg(((-1/2,), (1,)), ((0,), (-3/2,)), x) + x^(3/2)*meijerg(((-1/2, 1), ()), ((), (-3/2, 0)), x), True))")
  expect_equal(mi_fmt(meijerint_indefinite(x^a, x)), "Piecewise((x^(a + 1)*gamma(a + 1)/gamma(a + 2), Abs(x) < 1), (x^(a + 1)*meijerg(((-a,), (1,)), ((0,), (-a - 1,)), x) + x^(a + 1)*meijerg(((1, -a), ()), ((), (0, -a - 1)), x), True))")
  expect_equal(mi_fmt(meijerint_indefinite(exp(-x)*sin(x), x)), "2^(3/4)*sqrt(pi)*sqrt(x)*exp(-7*I*pi/8)*besseli(-1/2, sqrt(2)*x*exp_polar(I*pi/4))/8 - 3*2^(3/4)*sqrt(x)*exp(-5*I*pi/8)*besseli(5/2, sqrt(2)*x*exp_polar(I*pi/4))*gamma(-3/4)*gamma(-1/4)/(128*sqrt(pi)) + 2^(3/4)*sqrt(pi)*sqrt(x)*exp(-7*I*pi/8)*besselj(-1/2, sqrt(2)*x*exp_polar(I*pi/4))/8 - 3*2^(3/4)*sqrt(x)*exp(-5*I*pi/8)*besselj(5/2, sqrt(2)*x*exp_polar(I*pi/4))*gamma(-3/4)*gamma(-1/4)/(128*sqrt(pi)) - I*pi*x*besseli(1/2, x*exp_polar(I*pi/2))*besselj(1/2, x*exp_polar(I*pi/2))*gamma(1/4)/(16*gamma(5/4)) - 9*2^(1/4)*exp(-7*I*pi/8)*besseli(3/2, sqrt(2)*x*exp_polar(I*pi/4))*gamma(-3/4)*gamma(-1/4)/(128*sqrt(pi)*sqrt(x)) + 9*2^(1/4)*exp(-7*I*pi/8)*besselj(3/2, sqrt(2)*x*exp_polar(I*pi/4))*gamma(-3/4)*gamma(-1/4)/(128*sqrt(pi)*sqrt(x))")
  expect_equal(mi_fmt(meijerint_indefinite(1/(x^2 + 1), x)), "atan(x)")
  expect_equal(mi_fmt(meijerint_indefinite(x/(x^2 + 1), x)), "log(x^2 + 1)/2")
  expect_equal(mi_fmt(meijerint_indefinite(sin(x)^2, x)), "x/2 - sin(2*x)/4")
  expect_equal(mi_fmt(meijerint_indefinite(exp(a*x), x)), "exp(a*x)/a")
  expect_equal(mi_fmt(meijerint_indefinite(Si(x), x)), "x*Si(x) + cos(x)")
  expect_equal(mi_fmt(meijerint_indefinite(Ci(x), x)), "-x*log(x) + x*log(x^2)/2 + x*Ci(x) - sin(x)")
  expect_equal(mi_fmt(meijerint_indefinite(erfc(x), x)), "-x*erf(x) + x - exp(-x^2)/sqrt(pi)")
  expect_equal(mi_fmt(meijerint_indefinite(fresnels(x), x)), "3*x*fresnels(x)*gamma(3/4)/(4*gamma(7/4)) + 3*cos(pi*x^2/2)*gamma(3/4)/(4*pi*gamma(7/4))")
  expect_equal(mi_fmt(meijerint_indefinite(besselk(0, x), x)), "x*meijerg(((1/2,), ()), ((0, 0), (-1/2,)), x^2/4)/4")
  expect_equal(mi_fmt(meijerint_indefinite(log(x)^2, x)), "Piecewise((0, (Abs(x) < 1) & (1/Abs(x) < 1)), (x*log(x)^2 - 2*x*log(x) + 2*x, Abs(x) < 1), (x*log(1/x)^2 + 2*x*log(1/x) + 2*x, 1/Abs(x) < 1), (2*x*meijerg(((0,), (1, 1, 1)), ((0, 0, 0), (-1,)), x) + 2*x*meijerg(((0, 1, 1, 1), ()), ((), (-1, 0, 0, 0)), x), True))")
  expect_equal(mi_fmt(meijerint_indefinite(log(x + 1), x)), "Piecewise((0, (Abs(x + 1) < 1) & (1/Abs(x + 1) < 1)), (-x + (x + 1)*log(x + 1) - 1, Abs(x + 1) < 1), (-x - (x + 1)*log(1/(x + 1)) - 1, 1/Abs(x + 1) < 1), (-(x + 1)*meijerg(((0,), (1, 1)), ((0, 0), (-1,)), x + 1) + (x + 1)*meijerg(((0, 1, 1), ()), ((), (-1, 0, 0)), x + 1), True))")
  expect_equal(mi_fmt(meijerint_indefinite(x*log(x), x)), "Piecewise((0, (Abs(x) < 1) & (1/Abs(x) < 1)), (x^2*log(x)/2 - x^2/4, Abs(x) < 1), (-x^2*log(1/x)/2 - x^2/4, 1/Abs(x) < 1), (-x^2*meijerg(((-1,), (1, 1)), ((0, 0), (-2,)), x) + x^2*meijerg(((-1, 1, 1), ()), ((), (-2, 0, 0)), x), True))")
  expect_equal(mi_fmt(meijerint_indefinite(x^2*sin(x), x)), "-x^2*cos(x) + 2*x*sin(x) + 2*cos(x)")
  expect_equal(mi_fmt(meijerint_indefinite(exp(-x^2)*x, x)), "-exp(-x^2)/2")
  expect_equal(mi_fmt(meijerint_indefinite(sin(2*x + 3), x)), "-cos(2*x + 3)/2")
  expect_equal(mi_fmt(meijerint_definite(x, x, 0, 0)), "(0, True)")
  expect_equal(mi_fmt(meijerint_definite(x, x, oo, oo)), "(0, True)")
  expect_equal(mi_fmt(meijerint_definite((x + 1)^3*exp(-x), x, 0, oo)), "(16, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-((x - mu)/(2*sigma))^2), x, 0, oo)), "(sqrt(pi)*sigma*(2 - erfc(mu/(2*sigma))), True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-mu*x)*exp(sigma*x), x, 0, oo)), "(-1/(sigma*(-mu/sigma + 1)), (mu - sigma > 0) & Ne(mu/sigma, 1))")
  expect_equal(mi_fmt(meijerint_definite(exp(x), x, -oo, 2)), "(exp(2), True)")
  expect_equal(mi_fmt(meijerint_definite(exp(x), x, 0, sym_I)), "(I*(-I*exp(I) + I), True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x), x, 0, x)), "((-exp(-exp(I*arg(x))*Abs(x) - I*arg(x))/Abs(x) + exp(-I*arg(x))/Abs(x))*exp(I*arg(x))*Abs(x), (Abs(x) > 0) & (1/Abs(x) > 0) & Ne(1/Abs(x), 0) & (Abs(arg(exp(I*arg(polar_lift(x))))) < pi/2))")
  expect_equal(mi_fmt(meijerint_definite(exp(-x^2), x, -oo, oo)), "(sqrt(pi), True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-Abs(x)), x, -oo, oo)), "(2, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-(2*x - 3)^2), x, -oo, oo)), "(sqrt(pi)/2, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-Abs(2*x - 3)), x, -oo, oo)), "(1, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-((x - mu)/sigma)^2/2)/sqrt(2*S_Pi*sigma^2), x, -oo, oo)), "(1, True)")
  expect_equal(mi_fmt(meijerint_definite(sinc(x)^2, x, -oo, oo)), "(pi, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x)*sin(x), x, 0, oo)), "(1/2, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x)*sin(x)*x, x, 0, oo)), "(1/2, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x)*sin(x)*x^2, x, 0, oo)), "(1/2, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x)*sin(x)*x^3, x, 0, oo)), "(0, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x)*sin(x + a), x, 0, oo)), "(sin(a)/2 + cos(a)/2, True)")
  expect_equal(mi_fmt(meijerint_definite(meijerg(list(), list(), list(a/2), list(-a/2), x/4)*meijerg(list(), list(), list(b/2), list(-b/2), x/4)*x^(s - 1), x, 0, oo)), "(4*(1/4)^(1 - s)*gamma(1 - 2*s)*gamma(a/2 + b/2 + s)/(gamma(-a/2 + b/2 - s + 1)*gamma(a/2 - b/2 - s + 1)*gamma(a/2 + b/2 - s + 1)), (re(s) < 1/2) & (re(s) < 1) & (re(a)/2 + re(b)/2 + re(s) > 0))")
  expect_equal(mi_fmt(meijerint_definite(sin(x^a)*sin(x^b), x, 0, oo)), "None")
  expect_equal(mi_fmt(meijerint_definite((2 - x)^alpha*sin(alpha/x), x, 0, 2)), "(sqrt(pi)*alpha*meijerg(((), (alpha/2 + 1/2, alpha/2 + 1)), ((0, 0, 1/2), (-1/2,)), alpha^2/16)*gamma(alpha + 1)/4, True)")
  expect_equal(mi_fmt(meijerint_definite(x^ap, x, 0, bp)), "(bp*bp^ap/(ap + 1), True)")
  expect_equal(mi_fmt(meijerint_definite(x^sp*exp(-ap*x^2), x, -oo, oo)), "((-1)^sp*ap^(1/2 - sp/2)*gamma(sp/2 + 1/2)/(2*ap) + ap^(1/2 - sp/2)*gamma(sp/2 + 1/2)/(2*ap), True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x)*besselj(0, x), x, 0, oo)), "(sqrt(2)/2, True)")
  expect_equal(mi_fmt(meijerint_definite(1/(1 + x^2), x, 0, oo)), "(pi/2, True)")
  expect_equal(mi_fmt(meijerint_definite(sin(x)/x, x, 0, oo)), "(pi/2, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x^2)*cos(x), x, 0, oo)), "(sqrt(pi)*exp(-1/4)/2, True)")
  expect_equal(mi_fmt(meijerint_definite(x*exp(-x), x, 0, oo)), "(1, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-ap*x), x, 0, oo)), "(1/ap, True)")
  expect_equal(mi_fmt(meijerint_definite(cos(x)/(1 + x^2), x, 0, oo)), "(sqrt(pi)*(-sqrt(pi)*sinh(1) + sqrt(pi)*cosh(1))/2, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x)*x^(s - 1), x, 0, oo)), "(gamma(s), re(s) > 0)")
  expect_equal(mi_fmt(meijerint_definite(besselj(0, x), x, 0, oo)), "(1, True)")
  expect_equal(mi_fmt(meijerint_definite(besselj(a, z)*besselj(b, z)/z, z, 0, oo)), "(gamma(a/2 + b/2)/(2*gamma(-a/2 + b/2 + 1)*gamma(a/2 - b/2 + 1)*gamma(a/2 + b/2 + 1)), re(a)/2 + re(b)/2 > 0)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x^2), x, 0, 1)), "(sqrt(pi)*erf(1)/2, True)")
  expect_equal(mi_fmt(meijerint_definite(x^2, x, 1, 3)), "(26/3, True)")
  expect_equal(mi_fmt(meijerint_definite(exp(-x)/(1 + x), x, 0, oo)), "(E*expint(1, 1), True)")
  expect_equal(mi_fmt(meijerint_definite(log(x)*exp(-x), x, 0, oo)), "(-EulerGamma, True)")
  expect_equal(mi_fmt(meijerint_definite(sin(x)^2/x^2, x, 0, oo)), "(pi/2, True)")
  expect_equal(mi_fmt(meijerint_definite(x^(s - 1)/(1 + x), x, 0, oo)), "(pi/sin(pi*s), (re(s) > 0) & (re(s) < 1))")
  expect_equal(mi_fmt(meijerint_definite(exp(-ap*x^2)*cos(bp*x), x, 0, oo)), "(sqrt(pi)*exp(-bp^2/(4*ap))/(2*sqrt(ap)), True)")
  expect_equal(mi_fmt(meijerint_definite(sqrt(x)*exp(-x), x, 0, oo)), "(sqrt(pi)/2, True)")
  expect_equal(mi_fmt(meijerint_definite(erfc(x), x, 0, oo)), "(1/sqrt(pi), True)")
  expect_equal(mi_fmt(meijerint_definite(cos(x)*exp(-x), x, 0, oo)), "(1/2, True)")
  expect_equal(mi_fmt(meijerint_inversion(1/(s^2 + 1), s, t)), "sin(t)*Heaviside(t)")
  expect_equal(mi_fmt(meijerint_inversion(s/(s^2 + 1), s, t)), "cos(t)*Heaviside(t)")
  expect_equal(mi_fmt(meijerint_inversion(exp(-s)/s, s, t)), "Heaviside(t - 1)")
  expect_equal(mi_fmt(meijerint_inversion(1/sqrt(1 + s^2), s, t)), "Heaviside(t)*besselj(0, t)")
  expect_equal(mi_fmt(meijerint_inversion(sqrt(s)/sqrt(1 + s^2), s, t)), "None")
  expect_equal(mi_fmt(meijerint_inversion(exp(s^2), s, t)), "None")
  expect_equal(mi_fmt(meijerint_inversion(exp(-s^2), s, t)), "None")
  expect_equal(mi_fmt(meijerint_inversion(sqrt(S_Pi/ap)*exp(-2*sqrt(ap)*sqrt(s)), s, t)), "exp(-ap/t)*Heaviside(t)/t^(3/2)")
  expect_equal(mi_fmt(meijerint_inversion(sqrt(S_Pi/r)*exp(-2*sqrt(r)*sqrt(s)), s, t)), "Piecewise((exp(-r/t)*Heaviside(t)/t^(3/2), Ne(sqrt(polar_lift(r)), 0) & (re(exp(-I*pi/4)*sqrt(polar_lift(r))) > 0) & (re(exp(I*pi/4)*sqrt(polar_lift(r))) > 0)), (InverseLaplaceTransform(sqrt(pi)*sqrt(1/r)*exp(-2*sqrt(r)*sqrt(s)), s, t, _None), True))")
  expect_equal(mi_fmt(meijerint_inversion(exp(r*s), s, t)), "DiracDelta(r + t)")
  expect_equal(mi_fmt(meijerint_inversion(exp((1 + 2*sym_I)*s), s, t)), "None")
  expect_equal(mi_fmt(meijerint_inversion(exp(z*s), s, t)), "Piecewise((DiracDelta(t + z), Eq(im(z), 0)))")
  expect_equal(mi_fmt(meijerint_inversion(1/s, s, t)), "Heaviside(t)")
  expect_equal(mi_fmt(meijerint_inversion(1/s^2, s, t)), "t*Heaviside(t)")
  expect_equal(mi_fmt(meijerint_inversion(1/(s + 1), s, t)), "exp(-t)*Heaviside(t)")
  expect_equal(mi_fmt(meijerint_inversion(1/(s + 1)^2, s, t)), "t*exp(-t)*Heaviside(t)")
  expect_equal(mi_fmt(meijerint_inversion(1/sqrt(s), s, t)), "None")
  expect_equal(mi_fmt(meijerint_inversion(exp(-2*s)/s^2, s, t)), "(t - 2)*Heaviside(t - 2)")
  expect_equal(mi_fmt(meijerint_inversion(1/(s^2 - 1), s, t)), "sinh(t)*Heaviside(t)")
  expect_equal(mi_fmt(meijerint_inversion(1/(s*(s + 1)), s, t)), "(t - t*exp(-t))*Heaviside(t)/t")
})
